<script setup lang="ts">
import QueryPanel from '../components/QueryPanel.vue';
import QueryField from '../components/QueryField.vue';
import ListPanel from '../components/ListPanel.vue';
import {computed,onMounted,reactive,ref} from 'vue';import {ElMessage} from 'element-plus';import { Plus, Search } from 'lucide-vue-next';import {api} from '../api';import {post,dateText,errorText} from '../saas';import {useSessionStore} from '../stores/session';import ProvincePageState from '../components/ProvincePageState.vue';import './ProvincePages.css';
const session=useSessionStore(),canWrite=computed(()=>session.user?.accountLevel==='PROVINCE'&&session.user.permissions.includes('system:organization:update'));const rows=ref<any[]>([]),options=ref<any[]>([]),loading=ref(false),error=ref(''),saving=ref(false),total=ref(0),page=ref(1),q=ref(''),status=ref(''),workspaceId=ref(''),dialog=ref(false),history=ref<any>(null);const stages:Record<string,string>={PREPARING:'筹备中',SUBMITTED:'已申报',REVIEWING:'审核中',RECTIFYING:'整改中',ACCEPTED:'已验收',OPERATING:'运行中'};const form=reactive({workspaceId:'',stage:'PREPARING',responsibleName:'',planDate:'',summary:'',reviewComment:''});
async function load(){loading.value=true;error.value='';try{if(!options.value.length)options.value=(await api<any>('/oversight/options')).workspaces;const p=new URLSearchParams({page:String(page.value),pageSize:'20'});if(q.value.trim())p.set('q',q.value.trim());if(status.value)p.set('status',status.value);if(workspaceId.value)p.set('workspaceId',workspaceId.value);const r=await api<any>(`/oversight/pilots?${p}`);rows.value=r.items;total.value=r.total}catch(e){error.value=errorText(e)}finally{loading.value=false}}
function search(){page.value=1;load()}function open(row?:any){Object.assign(form,{workspaceId:row?.workspaceId??options.value[0]?.id??'',stage:row?.stage??'PREPARING',responsibleName:row?.responsibleName??'',planDate:row?.planDate?.slice(0,10)??'',summary:row?.summary??'',reviewComment:row?.reviewComment??''});dialog.value=true}
async function save(){if(!form.workspaceId||!form.responsibleName.trim()||form.summary.trim().length<5)return ElMessage.warning('请选择城市，填写负责人及至少5字的试点进展');saving.value=true;try{await post('/oversight/pilots',{...form,planDate:form.planDate?new Date(form.planDate).toISOString():undefined});dialog.value=false;ElMessage.success('试点进度已保存');await load()}catch(e){ElMessage.error(errorText(e))}finally{saving.value=false}}
onMounted(async()=>{try{options.value=(await api<any>('/oversight/options')).workspaces}catch(e){error.value=errorText(e);return}await load()});

function resetQueryFilters() {
  q.value = '';
  workspaceId.value = '';
  status.value = '';
  page.value = 1;
  search();
}
</script>
<template><section class="province-page"><h1 class="sr-only">试点管理</h1><QueryPanel :loading="loading" @search="search" @reset="resetQueryFilters">
<QueryField label="关键词" keyword><el-input aria-label="关键词" v-model="q" :prefix-icon="Search" clearable placeholder="搜索城市、负责人或进展" /></QueryField>
<QueryField label="城市"><el-select aria-label="城市" v-model="workspaceId" clearable placeholder="全部城市" @change="search"><el-option v-for="o in options" :key="o.id" :label="o.cityName" :value="o.id"/></el-select></QueryField>
<QueryField label="阶段"><el-select aria-label="阶段" v-model="status" clearable placeholder="全部阶段" @change="search"><el-option v-for="(label,key) in stages" :key="key" :label="label" :value="key"/></el-select></QueryField>
</QueryPanel>
<ListPanel title="试点进度列表" :total="error ? undefined : (total)">
<template #actions><el-button v-if="canWrite" type="primary" :icon="Plus" @click="open()">维护试点进度</el-button></template>
<ProvincePageState :error="error" :loading="loading" @retry="load"><el-table :data="rows" empty-text="没有符合条件的试点记录"><el-table-column label="城市" min-width="120"><template #default="{row}">{{row.cityName??row.workspace?.cityName}}</template></el-table-column><el-table-column label="当前阶段" width="120"><template #default="{row}"><el-tag :type="row.stage==='OPERATING'||row.stage==='ACCEPTED'?'success':row.stage==='RECTIFYING'?'warning':'info'">{{stages[row.stage]??row.stage}}</el-tag></template></el-table-column><el-table-column label="负责人" prop="responsibleName" width="120"/><el-table-column label="计划日期" width="130"><template #default="{row}">{{row.planDate?.slice(0,10)||'—'}}</template></el-table-column><el-table-column label="试点进展" prop="summary" min-width="260" show-overflow-tooltip/><el-table-column label="更新时间" width="170"><template #default="{row}">{{dateText(row.updatedAt)}}</template></el-table-column><el-table-column label="操作" width="150" fixed="right"><template #default="{row}"><el-button link type="primary" @click="history=row">过程记录</el-button><el-button v-if="canWrite" link type="primary" @click="open(row)">维护</el-button></template></el-table-column></el-table><div class="province-pagination"><span>共 {{total}} 条</span><el-pagination v-model:current-page="page" :total="total" :page-size="20" layout="prev,pager,next" @current-change="load"/></div></ProvincePageState>
</ListPanel>
<el-dialog class="province-dialog" v-model="dialog" title="维护试点进度" width="650px" destroy-on-close><el-form label-position="top"><div class="province-form-grid"><el-form-item label="城市" required><el-select v-model="form.workspaceId"><el-option v-for="o in options" :key="o.id" :label="o.cityName" :value="o.id"/></el-select></el-form-item><el-form-item label="试点阶段" required><el-select v-model="form.stage"><el-option v-for="(label,key) in stages" :key="key" :label="label" :value="key"/></el-select></el-form-item><el-form-item label="负责人" required><el-input v-model="form.responsibleName" maxlength="40"/></el-form-item><el-form-item label="计划日期"><el-date-picker v-model="form.planDate" type="date" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="试点进展" required class="full"><el-input v-model="form.summary" type="textarea" :rows="4" maxlength="4000" show-word-limit/></el-form-item><el-form-item label="审核或整改意见" class="full"><el-input v-model="form.reviewComment" type="textarea" :rows="3" maxlength="2000"/></el-form-item></div></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存进度</el-button></template></el-dialog><el-drawer class="province-drawer" :model-value="!!history" title="试点过程记录" size="560px" @close="history=null"><template v-if="history"><el-descriptions :column="1" border><el-descriptions-item label="城市">{{history.cityName??history.workspace?.cityName}}</el-descriptions-item><el-descriptions-item label="阶段">{{stages[history.stage]}}</el-descriptions-item><el-descriptions-item label="进展">{{history.summary}}</el-descriptions-item><el-descriptions-item label="意见">{{history.reviewComment||'—'}}</el-descriptions-item></el-descriptions><el-timeline style="margin-top:24px"><el-timeline-item v-for="(log,index) in history.logs??[]" :key="index" :timestamp="dateText(log.at??log.createdAt)"><strong>{{stages[log.stage??log.toStage]??log.action??'进度更新'}}</strong><p class="province-log">{{log.summary??log.comment??log.reviewComment}} · {{log.actorName}}</p></el-timeline-item></el-timeline><el-empty v-if="!history.logs?.length" description="暂无过程记录" :image-size="60"/></template></el-drawer></section></template>
